const ui = key => copy[document.documentElement.lang === 'mr' ? 'mr' : document.documentElement.lang === 'hi' ? 'hi' : 'en'][key] || copy.en[key] || key;

const setLanguage = lang => { document.documentElement.lang = lang === 'mr' ? 'mr' : lang === 'hi' ? 'hi' : 'en'; document.querySelectorAll('[data-i18n]').forEach(el => { const value = copy[lang][el.dataset.i18n]; if(value) el.innerHTML=value; }); document.querySelectorAll('[data-ph]').forEach(el => { const value = copy[lang][el.dataset.ph]; if(value) el.placeholder=value; }); document.querySelectorAll('.lang').forEach(btn=>btn.classList.toggle('active',btn.dataset.lang===lang)); localStorage.setItem('work-language',lang); refreshModal(lang); if(!document.querySelector('#explore-view')?.hidden) renderExplore(activeExploreFilter); if(!document.querySelector('#workers-view')?.hidden) renderWorkers(); if(!document.querySelector('#profile-view')?.hidden && profileData){renderProfile(profileData);setProfileWage(profileData);} };
document.querySelectorAll('.lang').forEach(btn => btn.addEventListener('click',()=>setLanguage(btn.dataset.lang)));
const menuButton=document.querySelector('.menu-button'); const topbar=document.querySelector('.topbar'); menuButton?.addEventListener('click',()=>topbar.classList.toggle('mobile-nav-open')); document.querySelectorAll('.nav-links a').forEach(link=>link.addEventListener('click',()=>topbar.classList.remove('mobile-nav-open')));

const modal = document.querySelector('#modal');
let currentRole = 'farmer';
const refreshModal = lang => {
  const worker = currentRole === 'worker';
  const c = copy[lang] || copy.en;
  document.querySelectorAll('[data-role-field]').forEach(field => {
    const active = field.dataset.roleField === currentRole;
    field.hidden = !active;
    field.querySelectorAll('input,select').forEach(input => { input.disabled = !active; });
  });
  const kicker = document.querySelector('#modal-kicker');
  const title = document.querySelector('#modal-title');
  const subtitle = document.querySelector('#modal-subtitle');
  const submit = document.querySelector('#submit-label');
  if (kicker) kicker.textContent = worker
    ? (lang === 'mr' ? 'तुमचं पुढचं काम शोधा' : lang === 'hi' ? 'अपना अगला काम खोजें' : 'FIND YOUR NEXT WORK')
    : (lang === 'mr' ? 'कामाची गरज पोस्ट करा' : lang === 'hi' ? 'काम की ज़रूरत पोस्ट करें' : 'POST A REQUIREMENT');
  if (title) title.textContent = worker
    ? (lang === 'mr' ? 'योग्य काम शोधा.' : lang === 'hi' ? 'सही काम खोजें.' : 'Find the right work.')
    : (lang === 'mr' ? 'योग्य कामगार शोधा.' : lang === 'hi' ? 'सही मज़दूर खोजें.' : 'Find the right workers.');
  if (subtitle) subtitle.textContent = worker
    ? (lang === 'mr' ? 'तुम्ही काय करू शकता आणि कुठे आहात ते सांगा.' : lang === 'hi' ? 'आप क्या कर सकते हैं और कहाँ हैं बताएं.' : 'Tell us what you can do and where you are.')
    : (lang === 'mr' ? 'कामाबद्दल थोडी माहिती द्या.' : lang === 'hi' ? 'काम के बारे में थोड़ी जानकारी दें.' : 'Tell us a little about the work.');
  if (submit) submit.textContent = worker
    ? (lang === 'mr' ? 'माझ्यासाठी काम शोधा' : lang === 'hi' ? 'मेरे लिए काम खोजें' : 'Find work for me')
    : c.formSubmit;
};
const syncTeamFields = () => { const isTeam=document.querySelector('#worker-type')?.value==='team'; document.querySelectorAll('[data-team-field]').forEach(field=>{field.hidden=!isTeam;field.querySelectorAll('input').forEach(input=>{input.disabled=!isTeam;});}); };
document.querySelector('#worker-type')?.addEventListener('change',syncTeamFields);
const openModal = role => { currentRole=role; document.querySelector('#lead-form').hidden=false; modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; refreshModal(document.documentElement.lang==='mr'?'mr':document.documentElement.lang==='hi'?'hi':'en'); syncTeamFields(); syncRequiredFields(); setTimeout(()=>modal.querySelector('input')?.focus(),50); };
const closeModal = () => { modal.classList.remove('open'); modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; };
const showView = view => { document.querySelector('main').hidden=true; document.querySelector('footer').hidden=true; document.querySelectorAll('.app-view').forEach(v=>{v.hidden=true;v.classList.remove('view-enter');}); const active=document.querySelector(view); active.hidden=false; requestAnimationFrame(()=>active.classList.add('view-enter')); window.scrollTo({top:0,behavior:'smooth'}); };
const showHome = (updateHash=true) => { document.querySelector('main').hidden=false; document.querySelector('footer').hidden=false; document.querySelectorAll('.app-view').forEach(v=>v.hidden=true); if(updateHash && window.location.hash!=='#top') window.location.hash='top'; if(updateHash) window.scrollTo({top:0,behavior:'smooth'}); };
