const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const displayDate = value => value ? new Date(`${value}T00:00:00`).toLocaleDateString(document.documentElement.lang === 'mr' ? 'mr-IN' : document.documentElement.lang === 'hi' ? 'hi-IN' : 'en-IN', {day:'2-digit', month:'short', year:'numeric'}) : ui('dateToDiscuss');
